/* Update climate inputs independently of DEM; never auto-run RF analysis. */
(()=>{'use strict';const $=id=>document.getElementById(id),fields=['relLogK','relDN75','rainRate','relSource'],coords=['aLat','aLon','bLat','bLon'];
const panel=document.createElement('div');panel.className='climate-panel';panel.innerHTML=`<div class="climate-heading"><label>แหล่งข้อมูลภูมิอากาศ<select id="climateMode"><option value="auto">อัตโนมัติจากพิกัด A–B</option><option value="manual">กรอกเอง · ข้อมูลสำรวจ / ฐานข้อมูลอื่น</option></select></label><button type="button" id="climateRetry">โหลดข้อมูลใหม่</button></div><p id="climateStatus" role="status" aria-live="polite">กรอกพิกัด A และ B ให้ครบ</p><p class="note">ใช้พิกัดกึ่งกลางลิงก์บน WGS84 · LogK / dN75: กริด 0.25° จากไฟล์ใน Drive · R₀.₀₁: กริด 0.125° จาก ITU-R P.837-7 (ไม่มีไฟล์ฝนในโฟลเดอร์ Drive) · แทรกค่าแบบ bilinear</p><p class="note"><a href="https://drive.google.com/drive/folders/1KD_aZCMZNI1dnjCgEpXsFsxRR0VazQJu" target="_blank" rel="noopener">ไฟล์ต้นฉบับ LogK / dN75</a> · <a href="https://www.itu.int/rec/R-REC-P.837-7-201706-S/en" target="_blank" rel="noopener">ฐานข้อมูลฝน P.837-7</a><br>ชุดข้อมูลนำเข้า 27 ต.ค. 2026 · เก็บสำเนากริดไว้กับเว็บเพื่อโหลดเร็ว ไม่ซิงก์การแก้ไฟล์ Drive แบบทันที · เป็นสถิติระยะยาว ไม่ใช่ฝนปัจจุบัน</p>`;$('availabilityInputs').querySelector('h2').after(panel);
$('relDN75').closest('label').after($('rainRate').closest('label'));
let serial=0,timer,ready=null,pending=null,submitting=false;
const automatic=()=>$('climateMode').value==='auto',key=()=>coords.map(id=>$(id).value.trim()).join('|');
function endpoints(){const v=coords.map(id=>$(id).value.trim());if(v.some(x=>x===''))throw Error('กรอก Latitude / Longitude ของสถานี A และ B ให้ครบ');const n=v.map(Number);if(n.some(x=>!Number.isFinite(x))||Math.abs(n[0])>85||Math.abs(n[2])>85||Math.abs(n[1])>180||Math.abs(n[3])>180)throw Error('ตรวจพิกัด: Latitude −85 ถึง 85°, Longitude −180 ถึง 180°');return [{lat:n[0],lon:n[1]},{lat:n[2],lon:n[3]}]}
function clear(){ready=null;for(const id of fields)$(id).value=''}
function controls(){for(const id of fields)$(id).readOnly=automatic();$('climateRetry').hidden=!automatic()}
function metadata(){return automatic()&&ready?.key===key()?{mode:'auto',...ready.data}:{mode:'manual'}}
async function update(force=false){if(!automatic())return;const k=key();if(!force&&ready?.key===k)return ready.data;if(!force&&pending?.key===k)return pending.promise;const seq=++serial;clear();let mid;try{const [a,b]=endpoints(),inv=MWMath.inverse(a,b);mid=inv.distance===0?a:MWMath.direct(a,inv.bearing,inv.distance/2)}catch(e){$('climateStatus').textContent=e.message;panel.dataset.state='waiting';throw e}
$('climateStatus').textContent='กำลังโหลดกริดสำหรับกึ่งกลางลิงก์…';panel.dataset.state='loading';
const promise=(async()=>{try{const data=await MWClimate.lookup(mid.lat,mid.lon);if(seq!==serial||k!==key()||!automatic())throw Error('พิกัดเปลี่ยนระหว่างโหลด กรุณารอข้อมูลชุดใหม่');ready={key:k,data};$('relLogK').value=data.logK.toFixed(8);$('relDN75').value=data.dN75.toFixed(8);$('rainRate').value=data.r001.toFixed(8);$('relSource').value=data.source+'; '+data.lat.toFixed(6)+', '+data.lon.toFixed(6);$('climateStatus').textContent=`โหลดแล้ว · กึ่งกลางลิงก์ ${data.lat.toFixed(6)}, ${data.lon.toFixed(6)} · LogK ${data.logK.toFixed(5)} · dN75 ${data.dN75.toFixed(3)} N-units · R₀.₀₁ ${data.r001.toFixed(3)} mm/h`;panel.dataset.state='ready';dirty();return data}catch(e){if(seq===serial){clear();panel.dataset.state='error';$('climateStatus').textContent='ยังใช้คำนวณไม่ได้ · '+e.message+' · กดโหลดข้อมูลใหม่เพื่อลองอีกครั้ง'}throw e}finally{if(pending?.seq===seq)pending=null}})();pending={key:k,seq,promise};return promise}
function schedule(){clearTimeout(timer);++serial;pending=null;clear();panel.dataset.state='waiting';$('climateStatus').textContent='พิกัดเปลี่ยนแล้ว · รอโหลดข้อมูลใหม่';timer=setTimeout(()=>update().catch(()=>{}),350)}
for(const event of ['input','change'])$('mwForm').addEventListener(event,e=>{if(automatic()&&coords.includes(e.target.id))schedule()});
$('climateMode').addEventListener('change',()=>{++serial;pending=null;clearTimeout(timer);controls();if(automatic()){clear();update().catch(()=>{})}else{ready=null;panel.dataset.state='manual';$('climateStatus').textContent='โหมดกรอกเอง · ตรวจสอบค่าทั้งสามและระบุแหล่งข้อมูลก่อนคำนวณ'}dirty()});$('climateRetry').onclick=()=>update(true).catch(()=>{});
const example=$('example').onclick;$('example').onclick=()=>{example();if(automatic())schedule()};
const submit=$('mwForm').onsubmit;$('mwForm').onsubmit=async e=>{e.preventDefault();if(submitting||controller)return;submitting=true;try{clearTimeout(timer);if(automatic()){const k=key();$('status').textContent='กำลังตรวจข้อมูลภูมิอากาศตามพิกัด…';await update();if(k!==key()||!ready||ready.key!==k)throw Error('พิกัดเปลี่ยน กรุณากดคำนวณใหม่')}await submit(e)}catch(err){$('status').textContent='คำนวณไม่สำเร็จ · '+err.message}finally{submitting=false;controls()}};
$('climateMode').value='auto';controls();clear();globalThis.MWClimateUI={metadata,update};update().catch(()=>{});
})();
